package org.apache.commons.lang.text;

import java.io.*;
import java.io.Reader;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ArrayUtils;
import org.apache.commons.lang.SystemUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StrBuilder.appendFixedWidthPadLeft
 */
public class StrBuilder_appendFixedWidthPadLeft_TriageGen1Test {

    @Test
    public void testAppendFixedWidthPadLeft_WidthGreaterThanZero_PadNeeded() {
        StrBuilder sb = new StrBuilder();
        // obj="abc", width=5, padChar='0' -> "00abc"
        sb.appendFixedWidthPadLeft("abc", 5, '0');
        assertEquals("00abc", sb.toString());
        assertEquals(5, sb.length());
    }

    @Test
    public void testAppendFixedWidthPadLeft_WidthGreaterThanZero_NoPadNeeded_ExactLength() {
        StrBuilder sb = new StrBuilder();
        // obj="abc", width=3, padChar='0' -> "abc"
        sb.appendFixedWidthPadLeft("abc", 3, '0');
        assertEquals("abc", sb.toString());
        assertEquals(3, sb.length());
    }

    @Test
    public void testAppendFixedWidthPadLeft_WidthGreaterThanZero_NoPadNeeded_LongerThanWidth() {
        StrBuilder sb = new StrBuilder();
        // obj="abcdef", width=3, padChar='0' -> "def" (takes last 'width' chars)
        sb.appendFixedWidthPadLeft("abcdef", 3, '0');
        assertEquals("def", sb.toString());
        assertEquals(3, sb.length());
    }

    @Test
    public void testAppendFixedWidthPadLeft_WidthGreaterThanZero_NullObject() {
        StrBuilder sb = new StrBuilder();
        String nullText = "NULL";
        sb.setNullText(nullText);
        // obj=null, width=6, padChar=' ' -> " NULL" (nullText is "NULL", len 4, pad 2)
        sb.appendFixedWidthPadLeft(null, 6, ' ');
        assertEquals("  NULL", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_WidthZero() {
        StrBuilder sb = new StrBuilder("base");
        // width=0 should do nothing
        sb.appendFixedWidthPadLeft("abc", 0, '0');
        assertEquals("base", sb.toString());
        assertEquals(4, sb.length());
    }

    @Test
    public void testAppendFixedWidthPadLeft_WidthNegative() {
        StrBuilder sb = new StrBuilder("base");
        // width < 0 should do nothing
        sb.appendFixedWidthPadLeft("abc", -1, '0');
        assertEquals("base", sb.toString());
        assertEquals(4, sb.length());
    }

    @Test
    public void testAppendFixedWidthPadLeft_IntegerObject() {
        StrBuilder sb = new StrBuilder();
        // obj=123, width=5, padChar='*' -> "***123"
        sb.appendFixedWidthPadLeft(123, 5, '*');
        assertEquals("***123", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_FluentInterface() {
        StrBuilder sb = new StrBuilder();
        StrBuilder returned = sb.appendFixedWidthPadLeft("x", 2, '0');
        assertSame(sb, returned);
        assertEquals("0x", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_LargeWidth() {
        StrBuilder sb = new StrBuilder();
        // Test capacity increase
        sb.appendFixedWidthPadLeft("a", 10, 'b');
        assertEquals("bbbbbbbbba", sb.toString());
        assertEquals(10, sb.length());
    }
}
